    for (var j = 1; j < i; ++j) {
      var carsBefore = min(j, i-j);
      var speedDifference = abs(i - j).toDouble();

      final double maxTimeToCollide = sqrt(8 * carsBefore / speedDifference);
      final int floorMaxTime = maxTimeToCollide.floor();

      var additionalCatches = (floorMaxTime + 1) % 2 == 0 ? floorMaxTime : floorMaxTime - 1;
      collisionCount += additionalCatches;
    }

    if (minSpeed == -1 || collisionCount > minSpeed) {
      minSpeed = collisionCount;
    } else if (collisionCount == minSpeed && i != minSpeed) {
      break; 
    }
  }

  return minSpeed;
}

