        if (!bucket.contains(i)) {
          continue;
        }

        if (inserted) break;

        int nextNum = j == bucket.length ? Int.max : bucket[j];

        if ((nextNum > i && !inserted) || (i >= nextNum)) {
          insertIndex = j;

          if (insertIndex != null) {
            bucket.insert(insertIndex, i);
            inserted = true;

            break;
          } else {
            throw Exception('Invalid index $insertIndex');
          }
        }
      }
    }

    if (!inserted) {
      buckets.add([i]);
    }
  }

