      prefix += "9"; // Append '9' to make it a valid number

      StringBuilder builder = StringBuffer();

      // Add reversed version of prefix to create palindrome
      for (int i = prefix.length - 1; i >= 0; --i) {
        builder.write(prefix[i]);
      }

      palindromeDigits.add(builder.toString());

      // Check if current palindrome has same parity as n and is within range
      int numPalin = int.parse(palindromeDigits.last);
      bool sameParity = numPalin % 2 == n % 2;
      if (sameParity) {
        break;
      } else {
        palindromeDigits.removeLast(); // Remove last invalid palindrome
      }
    }

    // Select the smallest palindrome that meets our criteria
    return [int.parse(palindromeDigits.first)]; 
  } else {
    return [0];
  }
}

