class Solution {
  static int maxFill(List<List<int>> grid, int capacity) {
    var rows = grid.length;
    if (rows == 0) return 0;
    var cols = grid[0].length;

    List<double> waterLevel = List.filled(rows, -1); // Tracks highest water level per column.
    List<double> height = List.generate(cols, (_) => double.infinity); // Current fill height of each cell.

    for (var r = 0; r < rows; r++) {
      for (var c = 0; c < cols; c++) {
        if (grid[r][c] != 1) continue;

        final currWaterHeight = waterLevel[c];
        final newWaterHeight = (height[c] + currWaterHeight).clamp(0.0, capacity.toDouble());

        if (newWaterHeight > currWaterHeight) {
          waterLevel[c] = newWaterHeight;
          height[c] += newWaterHeight - currWaterHeight;
        }
      }
    }

    return height.fold(0.0, (sum, val) => sum + val.roundToDouble()).toInt();
  }
}

